// Define the function signature using typedef
typedef int (*Operation)(int a, int b);

// Functions matching the signature
int fn_A(int a, int b) { return a + b; }
int fn_B(int a, int b) { return a * b; }

// Array of function pointers (Dispatch Table)
Operation HandlerTable[] = {
    fn_A,
    fn_B
};

// Alternate declaration syntax (less common with typedef)
// int (*AltTable[])(int, int) = { fn_A, fn_B };

// Invocation: Executes fn_B(5, 3)
int result = HandlerTable[1](5, 3);

// Function pointer accessed directly
Operation p_fn = HandlerTable[0];
int res2 = p_fn(10, 2);
